            break

    for c in range(w):
        if all(g[r][c] == g[0][c] for r in range(h)) and g[0][c] != 0:
            anchor_col = c
            break

    vertical = anchor_row is not None

    result = [[0] * w for _ in range(h)]

    if vertical:
        result[anchor_row] = list(g[anchor_row])
        for c in range(w):
