                for i, v in enumerate(nonz[:3]):
                    result[i + 6][c] = v
            elif count == 1:
                row = 6 if first_r <= 2 else 8
                result[row][c] = nonz[0]
            else:
                result[6][c] = nonz[0]
                result[7][c] = nonz[1]
